    fun newQualificationWords()=expectedWords
    private fun word(app:ByteArray,pc:Long):Long {
        require(pc>=0x1021000L&&pc and 3L==0L&&pc-0x1021000L<=app.size-4L)
        return ByteBuffer.wrap(app,Math.toIntExact(pc-0x1021000L),4).order(ByteOrder.LITTLE_ENDIAN).int.toLong() and 0xffffffffL
    }
    fun validateNewWords(app:ByteArray) {
        for((pc,w) in newQualificationWords())require(word(app,pc)==w) {"Selected complete configuration consumer word differs at "+pc.toString(16)}
    }
    fun observe(image:FirmwareImage):Map<String,Any?> {
        val app=image.decode("section4");validateNewWords(app)
        // Validate reused contracts once, without rerunning their mutation suites.
        val reused=BaseParameterContracts.observe(image)
        validateReusedCommand5(app)
        val records=(0 until 71).map {0x15aac40L+12*it}
        val selected=records.first {word(app,it) and 255L==61L}
        require(selected==0x15aaf10L&&word(app,selected)==0x53dL&&word(app,selected+4)==0x15aa608L&&word(app,selected+8)==0x15aa88cL)
        val row=0x15aa608L+3*0x30
        val values=(0..12).map {word(app,row+4*it)}
        require(values==listOf(0x113L,0x3d0003L,11L,2L,128L,8L,32L,280L,3L,32L,4L,34L,295L))
        require((0 until 3).none {word(app,0x15aa608L+it*0x30+4)==0x3d0003L})
        val parameters=(32..34).map {i->val p=0x15ac5f0L+16*i
            mapOf("index" to i,"base" to word(app,p),"dataAddress" to word(app,p+4),"minimum" to word(app,p+8),"maximum" to word(app,p+12))}
        require(parameters.map {it["base"]}==listOf(0xff703000L,0xff704000L,0xff704000L))
        require(parameters.map {it["dataAddress"]}==listOf(0xff703040L,0xff704040L,0xff704044L))
        fun base(index:Int)=mapOf("index" to index,"group" to BaseParameterContracts.groupIndices[index],"base" to BaseParameterContracts.bases[index])
        return mapOf("evidenceClass" to "DAT","newCompleteWords" to newQualificationWords().size,"newMutationBits" to newQualificationWords().size*32,
            "eligibleBaseIndices" to listOf(3,9,12),"eligibleGroups" to listOf(10,16,19),"eligibleBases" to listOf(0xff704000L,0xff706000L,0xfffae000L),"commands" to listOf(5,6),
            "consumer" to mapOf("entry" to 0x11f69e4L,"endExclusive" to 0x11f74b0L,"bodyComplete" to true,"embeddedJumpTablesAreData" to listOf(listOf(0x11f6a20L,0x11f6a3cL),listOf(0x11f7318L,0x11f7330L)),"opaquePrerequisiteCalls" to listOf(0x11f60a4L,0x11f6234L)),
            "lookup" to mapOf("entry" to 0x11f6038L,"table" to 0x15aac40L,"records" to 71,"stride" to 12,"selectedRecord" to selected,"resourceId" to 61,"type" to 5,"configurationTable" to 0x15aa608L,"prerequisiteTable" to 0x15aa88cL),
            "selection" to mapOf("selector" to 0x3d0003L,"rowIndex" to 3,"stride" to 48,"rowBase" to row,"rowBaseWordAndCompleteRecord" to values,"recordStartsAtSelector" to row+4,"recordEndExclusive" to row+52,"lastValueIsCurrentRecordFinalWord" to true,"physicalNameFrequencyOrUnits" to "UNKNOWN: no name/text/unit binding in this bounded record layout"),
            "upstreamPairTarget" to base(2),"command5And6Target" to base(3),"parameters" to parameters,
            "command6" to mapOf("entry" to 0x11f815cL,"eligibleIndices" to listOf(3,9,12),"writes" to listOf(mapOf("offset" to 0,"source" to "r1"),mapOf("offset" to 8,"source" to "r2")),"command" to 6,"commandPollMask" to 7,"statusOffset" to 240,"statusPollMask" to 1,"ordinaryReturn" to 0),
            "successContinuation" to selectedSuccessContinuation(),"reusedBaseParameterContract" to reused,
            "namingScope" to "15AA0AC contains numeric resource IDs/values; selected descriptor15AAF10 contains type and numeric-table pointers. Full consumer uses no name/frequency/log-text pointer binding. This is not a global absence claim.",
            "deviceSemantics" to semanticBoundary(),"oldMutationSuitesRepeated" to false)
    }
    fun selectedSuccessContinuation()=listOf(
        mapOf("order" to 1,"call" to 0x11f7100L,"operation" to "command5 index3/group10; current request uncommitted"),
        mapOf("order" to 2,"call" to 0x11f6f88L,"operation" to "index2/group9 writes base+0=128,base+8=8; command3; mask7 poll then base+F0 mask1 poll"),
        mapOf("order" to 3,"call" to 0x11f6fa4L,"operation" to "parameter32/group9 base+40=280; command2; mask7 poll"),
        mapOf("order" to 4,"call" to 0x11f7120L,"operation" to "index3/group10 writes base+0=32,base+8=4; command6; mask7 poll then base+F0 mask1 poll"),
        mapOf("order" to 5,"call" to 0x11f6fe4L,"operation" to "parameter34/group10 base+44=295 from current record final word at row-base+30; command2; mask7 poll"),
        mapOf("order" to 6,"call" to 0x11f7134L,"operation" to "resource61 branch restores saved parameter33/group10 base+40=0; command2; mask7 poll"),
        mapOf("order" to 7,"call" to 0x11f6d08L,"operation" to "read selector5 through11F7DA8; compare with11; if different call11F7D20(5,11); errors return through11F6BAC"))
    fun semanticBoundary()=mapOf(
        "command5PhysicalEffect" to "UNKNOWN","command6PhysicalEffect" to "UNKNOWN beyond software pair writes and two completion polls",
        "provedRelationship" to "Command5 precedes configuration of a different base pair and command2 parameter; command6 later submits a new pair to the same index as command5.",
        "notProved" to listOf("command5 changes F0/status or pair visibility","disable/isolation/cancel/clock/PLL/power effect","command6 resumes or reverses command5","old/new pair atomicity across groups","timing,IRQ,DMA or output consumer"),
        "ackOnlyCandidate" to "REJECTED: clearing command5 to0 would only fabricate the polled completion; no device operation is established",
        "standaloneCommand5DeviceOperationEstablished" to false,
        "minimumMissingEvidence" to "A documented or measured relation from command5/6 to an independently observable device state (pair visibility/F0/operation state/output), including whether and when command5 changes it and command6 changes it back or commits it. Present DAT and stopped pre5 state supply no such observation.")
    private fun validateReusedCommand5(app:ByteArray) {
        val words="e350000c 13500009 13a03001 03a03000 e3500003 03a03000 12033001 e3530000 1a000008 e92d4800 e28db004 e30c3950 e340315a e3a01005 e7930100 ebfffeba e3a00000 e8bd8800 e3e0001d e12fff1e".split(' ').map {it.toLong(16)}
        for((i,w) in words.withIndex())require(word(app,0x11f810cL+i*4)==w) {"Reused command5 wrapper differs"}
        for((pc,w) in mapOf(0x11f7100L to 0xeb000401L,0x11f7104L to 0xe2504000L,0x11f7108L to 0x1afffefaL,0x11f710cL to 0xeaffff98L))require(word(app,pc)==w) {"Reused outer command5 edge differs"}
    }
}
